-- Fatia D: retenção e exclusão (migration 062). Reverte tudo; sucesso = "RESULTADO: ... PASSOU".
do $$ declare v_driver uuid; v_guard uuid; v_token text := 'TESTE-ret-' || gen_random_uuid(); v_sub uuid; v_s uuid; v_s2 uuid; v_route uuid; v_cid uuid; n integer; v_ok boolean; r json; v_pa timestamptz; c2 jsonb := jsonb_build_object('version','t1','sha256','abc','snapshot','texto aceito','method','remote','checks',jsonb_build_array(jsonb_build_object('text','a','checked',true),jsonb_build_object('text','b','checked',true)));
begin
  select user_id into v_driver from driver_profiles limit 1; select user_id into v_guard from guardians limit 1;
  if v_driver is null or v_guard is null then raise exception 'FALHOU 0: precisa de 1 motorista e 1 responsável'; end if;
  insert into capture_links (driver_id, shift, school, token) values (v_driver,'morning','Escola Teste',v_token);
  insert into routes (driver_id,name,direction,shift,weekdays) values (v_driver,'TESTE rota ret','both','morning','{1}') returning id into v_route;
  perform set_config('request.jwt.claims', json_build_object('sub',v_guard,'role','authenticated')::text, true);
  r := submit_capture(v_token,'Criança Ret',null,'Rua X',true,null,'1','1',p_consent=>c2); v_sub := (r->>'submission_id')::uuid;
  perform set_config('request.jwt.claims', json_build_object('sub',v_driver,'role','authenticated')::text, true);
  r := approve_capture(v_sub); v_s := (r->>'student_id')::uuid;
  insert into route_stops (route_id,student_id,position,kind) values (v_route,v_s,1,'pickup');
  select purge_after into v_pa from students where id=v_s;
  if v_pa is not null then raise exception 'FALHOU 1: aluno ativo não deve ter prazo'; end if;
  update students set status='archived' where id=v_s;
  select purge_after into v_pa from students where id=v_s;
  if v_pa is null or v_pa < now()+interval '29 days' then raise exception 'FALHOU 2: arquivar deveria marcar prazo de 30 dias'; end if;
  update students set status='active' where id=v_s;
  select purge_after into v_pa from students where id=v_s;
  if v_pa is not null then raise exception 'FALHOU 3: desarquivar deveria limpar o prazo'; end if;
  perform set_config('request.jwt.claims', json_build_object('sub',v_guard,'role','authenticated')::text, true);
  select id into v_cid from consents where student_id=v_s and kind='child_data' and revoked_at is null;
  perform revoke_consent(v_cid);
  select purge_after into v_pa from students where id=v_s;
  if v_pa is null then raise exception 'FALHOU 4: suspender deveria marcar prazo'; end if;
  perform reauthorize_child(v_s, c2);
  select purge_after into v_pa from students where id=v_s;
  if v_pa is not null then raise exception 'FALHOU 5: reautorizar deveria limpar o prazo'; end if;
  perform revoke_consent((select id from consents where student_id=v_s and kind='child_data' and revoked_at is null));
  update students set purge_after = now()-interval '1 day', photo_path = v_s::text||'/foto.jpg' where id=v_s;
  select count(*) into n from erasure_ledger where student_id=v_s;
  if n<>0 then raise exception 'FALHOU 6: ledger deveria estar vazio'; end if;
  n := anonymize_due_students();
  if n < 1 then raise exception 'FALHOU 7: job deveria anonimizar vencidos'; end if;
  select count(*) into n from students where id=v_s and anonymized_at is not null and full_name='Aluno removido' and pickup_address is null and responsible_phone is null and photo_path is null;
  if n<>1 then raise exception 'FALHOU 8: dados pessoais não limpos'; end if;
  select count(*) into n from route_stops where student_id=v_s; if n<>0 then raise exception 'FALHOU 9: parada deveria sumir'; end if;
  select count(*) into n from guardian_student where student_id=v_s; if n<>0 then raise exception 'FALHOU 10: vínculo deveria sumir'; end if;
  select count(*) into n from erasure_ledger where student_id=v_s and reason='retention_30d'; if n<>1 then raise exception 'FALHOU 11: ledger deveria registrar'; end if;
  select count(*) into n from storage_purge_queue where path=v_s::text||'/foto.jpg'; if n<>1 then raise exception 'FALHOU 12: foto deveria entrar na fila'; end if;
  select count(*) into n from consents where student_id=v_s; if n<1 then raise exception 'FALHOU 13: evidência de consentimento deve ser mantida'; end if;
  v_ok := false; begin perform reauthorize_child(v_s, c2); exception when others then v_ok := true; end;
  if not v_ok then raise exception 'FALHOU 14: aluno removido não pode ser reautorizado'; end if;
  perform _anonymize_student(v_s,'admin',null,null);
  select count(*) into n from erasure_ledger where student_id=v_s; if n<>1 then raise exception 'FALHOU 15: anonimizar 2x não pode duplicar ledger'; end if;
  perform set_config('request.jwt.claims', json_build_object('sub',v_guard,'role','authenticated')::text, true);
  r := submit_capture(v_token,'Criança Rej',null,'Rua X',true,null,'1','1',p_consent=>c2); v_sub := (r->>'submission_id')::uuid;
  perform set_config('request.jwt.claims', json_build_object('sub',v_driver,'role','authenticated')::text, true);
  perform reject_capture(v_sub);
  select count(*) into n from capture_submissions where id=v_sub; if n<>0 then raise exception 'FALHOU 16: rejeitada deveria ser apagada'; end if;
  select count(*) into n from consents where submission_id=v_sub; if n<>0 then raise exception 'FALHOU 17: consentimento da rejeitada deveria sumir'; end if;
  perform set_config('request.jwt.claims', json_build_object('sub',v_guard,'role','authenticated')::text, true);
  r := submit_capture(v_token,'Criança Velha',null,'Rua X',true,null,'1','1',p_consent=>c2); v_sub := (r->>'submission_id')::uuid;
  update capture_submissions set created_at = now()-interval '31 days' where id=v_sub;
  perform purge_stale_submissions();
  select count(*) into n from capture_submissions where id=v_sub; if n<>0 then raise exception 'FALHOU 18: pendente >30 dias deveria sumir'; end if;
  r := submit_capture(v_token,'Criança Ped',null,'Rua X',true,null,'1','1',p_consent=>c2); v_sub := (r->>'submission_id')::uuid;
  perform set_config('request.jwt.claims', json_build_object('sub',v_driver,'role','authenticated')::text, true);
  r := approve_capture(v_sub); v_s2 := (r->>'student_id')::uuid;
  perform set_config('request.jwt.claims', json_build_object('sub',v_guard,'role','authenticated')::text, true);
  perform request_erasure(v_s2,'quero apagar'); perform request_erasure(v_s2,'de novo');
  select count(*) into n from erasure_requests where student_id=v_s2 and status='pending'; if n<>1 then raise exception 'FALHOU 19: pedido pendente deve ser único'; end if;
  v_ok := false; begin perform admin_decide_erasure((select id from erasure_requests where student_id=v_s2),true,null); exception when others then v_ok := true; end;
  if not v_ok then raise exception 'FALHOU 20: só admin decide'; end if;
  v_ok := false; begin perform admin_erase_student(v_s2); exception when others then v_ok := true; end;
  if not v_ok then raise exception 'FALHOU 21: só admin apaga'; end if;
  perform set_config('request.jwt.claims', json_build_object('sub',v_driver,'role','authenticated')::text, true);
  v_ok := false; begin perform request_erasure(v_s2,'x'); exception when others then v_ok := true; end;
  if not v_ok then raise exception 'FALHOU 22: motorista não pede exclusão'; end if;
  select count(*) into n from cron.job where jobname='kangu_retention_daily'; if n<>1 then raise exception 'FALHOU 23: job diário ausente'; end if;
  raise exception 'RESULTADO: lgpd_retencao_exclusao PASSOU';
end $$;
